  "settings.modelProvider.fieldHelp": "Om {field}",
  "settings.modelProvider.help.contextWindow": "Kontekstkapasiteten modellen kan behandle om gangen, i tokens. ZAICODE bruker dette til å håndtere kontekst.\nIkke overskrid modellens faktiske grense.",
  "settings.modelProvider.help.maxOutputTokens": "Maksimalt antall tokens en enkelt modellforespørsel kan generere.\nIkke overskrid modellens faktiske grense.",
  "settings.modelProvider.help.inputModalities": "Sett innholdstypene modellen kan motta:\n\n- **Tekst**: Mottar tekstinnhold. Påkrevd.\n- **Bilder**: Mottar bildeinnhold.\n- **Video**: Mottar videoinnhold.\n- **PDF**: Mottar PDF-dokumenter direkte.",
  "settings.modelProvider.help.outputModalities": "Innholdstypen på modellens svar. Bare tekst støttes for øyeblikket.",
  "settings.modelProvider.help.capabilities": "- **Strukturert utdata**: Støtter JSON Schema-begrensninger på utdatafelter, typer og struktur.\n- **Innbygd websøk**: Støtter modell-API-ens innebygde websøkfunksjon.\n- **Systemmeldinger midt i samtale**: Støtter innsetting av systeminstruksjoner under en samtale.\n\nIkke aktiver funksjoner modellen ikke støtter.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Sett resonnivåene som er tilgjengelige i chatten. **De må være ordnet fra lavest til høyest resonneringsinnsats**.\nIkke konfigurer resonnivåer modellen ikke støtter.",
  "settings.modelProvider.help.reasoningLevelMapping": "Bruk et CEL-uttrykk for å kartlegge gjeldende resonneringsnivå, `reasoningLevel`, til felter i modell-API-forespørselen. JSON-objektet som uttrykket returnerer, flettes inn i forespørselsteksten.",
  "settings.modelProvider.help.advanced": "**MFJS-verktøyskjema**: Aktiverer Moonshot Flavored JSON Schema-kompatibilitet, vanligvis brukt av Moonshots Kimi-modell-API. Aktiver bare når modell-API-en krever dette formatet.",
  "settings.modelProvider.help.followRecommendedConfig": "Samsvarer med anbefalt konfigurasjon basert på modell-ID, Base URL og API-format. ZAICODE oppdaterer anbefalingene fortløpende og synkroniserer dem automatisk til deg.\nNår du endrer en innstilling manuelt, blir den innstillingen manuelt administrert og slutter å følge anbefalingsoppdateringer; andre innstillinger forblir administrert av smart konfigurasjon.",
